create extension if not exists "uuid-ossp";
create type public.user_role as enum ('admin','user');
create type public.enquiry_status as enum ('new','contacted','closed');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, email text, role public.user_role not null default 'user', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.properties (id uuid primary key default uuid_generate_v4(), title text not null, slug text not null unique, description text not null, property_type text not null check(property_type in ('apartment','villa','house','studio','commercial')), location text not null, address text not null, city text not null, state text not null default 'Kerala', postal_code text not null, monthly_rent numeric not null check(monthly_rent > 0), security_deposit numeric not null default 0, bedrooms integer not null default 0 check(bedrooms>=0), bathrooms integer not null default 0 check(bathrooms>=0), area numeric not null check(area>0), area_unit text not null default 'sq ft', furnishing text not null check(furnishing in ('unfurnished','semi-furnished','furnished')), availability boolean not null default true, featured boolean not null default false, amenities text[] not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.property_images (id uuid primary key default uuid_generate_v4(), property_id uuid not null references public.properties(id) on delete cascade, storage_path text not null unique, image_url text, is_cover boolean not null default false, display_order integer not null default 0, created_at timestamptz not null default now());
create unique index one_cover_per_property on public.property_images(property_id) where is_cover;
create table public.enquiries (id uuid primary key default uuid_generate_v4(), property_id uuid not null references public.properties(id) on delete cascade, name text not null, phone text not null, email text not null, message text not null, status public.enquiry_status not null default 'new', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index properties_search_idx on public.properties using gin(to_tsvector('english', title || ' ' || location)); create index properties_filters_idx on public.properties(location, property_type, availability, monthly_rent); create index enquiries_property_idx on public.enquiries(property_id);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create trigger properties_updated before update on public.properties for each row execute procedure public.touch_updated_at(); create trigger profiles_updated before update on public.profiles for each row execute procedure public.touch_updated_at(); create trigger enquiries_updated before update on public.enquiries for each row execute procedure public.touch_updated_at();
alter table public.profiles enable row level security; alter table public.properties enable row level security; alter table public.property_images enable row level security; alter table public.enquiries enable row level security;
create policy "profiles own read" on public.profiles for select using(auth.uid()=id); create policy "admins manage profiles" on public.profiles for all using(public.is_admin()) with check(public.is_admin());
create policy "public reads available properties" on public.properties for select using(availability=true or public.is_admin()); create policy "admins manage properties" on public.properties for all using(public.is_admin()) with check(public.is_admin());
create policy "public reads images of visible homes" on public.property_images for select using(exists(select 1 from public.properties p where p.id=property_id and (p.availability or public.is_admin()))); create policy "admins manage images" on public.property_images for all using(public.is_admin()) with check(public.is_admin());
create policy "public creates enquiries" on public.enquiries for insert with check(true); create policy "admins manage enquiries" on public.enquiries for all using(public.is_admin()) with check(public.is_admin());
insert into storage.buckets(id,name,public) values ('property-images','property-images',true) on conflict(id) do nothing;
create policy "public property image access" on storage.objects for select using(bucket_id='property-images'); create policy "admin image uploads" on storage.objects for insert with check(bucket_id='property-images' and public.is_admin()); create policy "admin image updates" on storage.objects for update using(bucket_id='property-images' and public.is_admin()); create policy "admin image deletes" on storage.objects for delete using(bucket_id='property-images' and public.is_admin());
-- Promote an authenticated user after account creation: update public.profiles set role='admin' where email='admin@example.com';
